// Filter posts due to publish
const posts = $input.all().map(item => item.json);
const now = new Date();

const duePosts = posts.filter(post => {
  if (post.status !== 'scheduled') return false;

  const scheduledTime = new Date(post.scheduled_time);
  const timeDiff = now - scheduledTime;

  // Post within last hour window
  return timeDiff >= 0 && timeDiff <= 3600000;
});

console.log(`Found ${duePosts.length} posts due to publish`);

return duePosts.map(post => ({
  json: {
    ...post,
    publish_now: true,
    current_time: now.toISOString()
  }
}));

// Format content for platform
const post = $input.first().json;
const platform = post.platform?.toLowerCase() || 'facebook';

let formattedContent = post.content || '';
const hashtags = post.hashtags || '';

// Platform-specific formatting
switch(platform) {
  case 'twitter':
    // Twitter: 280 characters max
    if (formattedContent.length > 250) {
      formattedContent = formattedContent.substring(0, 247) + '...';
    }
    if (hashtags) {
      const maxContentLength = 280 - hashtags.length - 2;
      if (formattedContent.length > maxContentLength) {
        formattedContent = formattedContent.substring(0, maxContentLength - 3) + '...';
      }
      formattedContent = formattedContent + '\n\n' + hashtags;
    }
    break;

  case 'linkedin':
    // LinkedIn: 3000 characters max
    if (formattedContent.length > 2900) {
      formattedContent = formattedContent.substring(0, 2897) + '...';
    }
    if (hashtags) {
      formattedContent = formattedContent + '\n\n' + hashtags;
    }
    // Add professional tone for LinkedIn
    formattedContent = formattedContent.replace(/💰/g, '').replace(/🔥/g, '');
    break;

  case 'facebook':
    // Facebook: no strict limit, but keep it reasonable
    if (formattedContent.length > 5000) {
      formattedContent = formattedContent.substring(0, 4997) + '...';
    }
    if (hashtags) {
      formattedContent = formattedContent + '\n\n' + hashtags;
    }
    break;

  case 'instagram':
    // Instagram: 2200 characters max
    if (formattedContent.length > 2100) {
      formattedContent = formattedContent.substring(0, 2097) + '...';
    }
    if (hashtags) {
      formattedContent = formattedContent + '\n\n' + hashtags;
    }
    break;
}

return [{
  json: {
    ...post,
    formatted_content: formattedContent,
    platform,
    character_count: formattedContent.length
  }
}];

